//! Generated-file ownership, publication, and source fingerprinting.
//!
//! Only paths recorded in `bimetal.toml`, and files that carry Bimetal's banner,
//! may be replaced or removed; every other path is the user's.
//!
//! - `scratch` owns the `.bimetal` directory, the build lock, and staged files;
//! - `publish` installs a staged tree, or compares it with the published one;
//! - `fingerprint` decides when nothing needs to be built;
//! - `artifacts` names the native artifacts that a build installs beside
//!   the generated files;
//! - `native` records which sources built the installed native artifacts,
//!   such as the Python extension, and what else this machine's last build
//!   read.

mod artifacts;
mod fingerprint;
mod native;
mod publish;
mod scratch;

pub(crate) use artifacts::{Platform, is_library, native_file};
pub(crate) use fingerprint::{Fingerprint, LocalInputs, Sources, generated_up_to_date, tracked};
pub(crate) use native::{
    InstalledNative, forget_native, installed_native, record_native, recorded_local_inputs,
};
pub(crate) use publish::{
    OutOfSync, check_generated_files, check_records, reconcile_generated_files,
};
pub(crate) use scratch::{install, persist, project_lock, staging_directory, write};

/// The text that the first line of every generated text file contains, and
/// that marks a file as Bimetal's to replace.
pub(crate) const GENERATED_BANNER: &str = "AUTO-GENERATED BY Bimetal - DO NOT EDIT.";

/// Return the first line of a generated text file: a comment that holds
/// [`GENERATED_BANNER`], opened by `open` and closed by `close`, such as
/// `/*` and ` */`.
#[must_use]
pub(crate) fn banner(open: &str, close: &str) -> String {
    format!("{open} {GENERATED_BANNER} `bimetal build` overwrites this file.{close}\n")
}
